// IEEE-compatible translation helpers. Carnegie's auth endpoint and target
// language setting remain unchanged; only batching, caching and DOM writeback
// are shared with the tested IEEE implementation.
function TA(java, cache) {
    var token = cache.get("carnegie_ms_ts_auth");
    if (token && String(token).length > 20) {
        java.put("AUTH", String(token));
        return String(token);
    }
    token = java.get("AUTH");
    if (!token || String(token).length <= 20) {
        token = java.ajax("https://edge.microsoft.com/translate/auth");
        if (typeof token === "object" && token.toString) token = token.toString();
        java.put("AUTH", token);
    }
    token = String(token);
    cache.put("carnegie_ms_ts_auth", token, 3000);
    return token;
}

function TT(text, java, cache) {
    var targetLang = java.get("TARGET_LANG");
    if (!targetLang || String(targetLang).trim() === "") targetLang = "zh-Hans";
    var scalar = typeof text === "string" || text instanceof String;
    var texts = scalar ? [String(text)] : (text || []);
    var translated = [];
    var batches = [];
    var batchIndexes = [];
    var current = [];
    var currentIndexes = [];
    var currentChars = 0;
    var i;
    for (i = 0; i < texts.length; i++) {
        var original = String(texts[i]);
        translated[i] = original;
        if (!original.trim()) continue;
        var cacheKey = "mst_" + targetLang + ":" + original;
        var cached = cache.get(cacheKey);
        if (cached != null) {
            translated[i] = String(cached);
            continue;
        }
        if (current.length > 0 && (currentChars + original.length > 4000 || current.length >= 200)) {
            batches.push(current);
            batchIndexes.push(currentIndexes);
            current = [];
            currentIndexes = [];
            currentChars = 0;
        }
        current.push(original);
        currentIndexes.push(i);
        currentChars += original.length;
    }
    if (current.length > 0) {
        batches.push(current);
        batchIndexes.push(currentIndexes);
    }
    if (batches.length === 0) return scalar ? translated[0] : translated;

    var token = TA(java, cache);
    var urls = [];
    for (i = 0; i < batches.length; i++) {
        var options = JSON.stringify({
            "headers": {"Authorization": "Bearer " + token, "Content-Type": "application/json"},
            "method": "post",
            "body": JSON.stringify(batches[i])
        });
        urls.push("https://edge.microsoft.com/translate/translatetext?to=" + targetLang + "," + options);
    }

    var MAX_PARALLEL = 4;
    var WAVE_DELAY_MS = 500;
    for (var start = 0; start < urls.length; start += MAX_PARALLEL) {
        var end = Math.min(start + MAX_PARALLEL, urls.length);
        var waveUrls = [];
        for (i = start; i < end; i++) waveUrls.push(urls[i]);
        var responses = [];
        try {
            // Keep Legado's source limiter enabled; this local cap also protects
            // Microsoft's anonymous endpoint from a burst of requests.
            responses = java.ajaxAll(waveUrls, false);
        } catch (e) {
            responses = [];
        }
        for (var r = 0; r < responses.length && start + r < end; r++) {
            var response = responses[r];
            var raw = "";
            try {
                raw = response && typeof response.body === "function" ? response.body() : String(response);
            } catch (e) {
                raw = "";
            }
            var array = null;
            try { array = raw ? JSON.parse(String(raw)) : null; } catch (e) { array = null; }
            var batchIndex = start + r;
            if (!array || array.length !== batches[batchIndex].length) continue;
            for (var n = 0; n < array.length; n++) {
                if (!array[n] || !array[n].translations || !array[n].translations[0]) continue;
                var resultIndex = batchIndexes[batchIndex][n];
                var value = String(array[n].translations[0].text);
                translated[resultIndex] = value;
                cache.put("mst_" + targetLang + ":" + batches[batchIndex][n], value, 2592000);
            }
        }
        if (end < urls.length) {
            try { Packages.java.lang.Thread.sleep(WAVE_DELAY_MS); } catch (e) {}
        }
    }
    return scalar ? translated[0] : translated;
}

function TC(html, java, cache) {
    if (html == null || String(html).trim() === "") return html;
    var doc = org.jsoup.Jsoup.parse(String(html));
    var nodes = [];
    var texts = [];
    var elements = doc.select("*");
    for (var i = 0; i < elements.size(); i++) {
        var element = elements.get(i);
        var ancestor = element;
        var skip = false;
        while (ancestor != null) {
            if (ancestor.hasClass("notranslate")) {
                skip = true;
                break;
            }
            ancestor = ancestor.parent();
        }
        if (skip) continue;
        var direct = element.textNodes();
        for (var j = 0; j < direct.size(); j++) {
            var node = direct.get(j);
            var value = String(node.getWholeText());
            if (!value.trim()) continue;
            nodes.push(node);
            texts.push(value);
        }
    }
    if (texts.length === 0) return "" + doc.html();
    var translated = TT(texts, java, cache);
    for (var k = 0; k < nodes.length; k++) nodes[k].text(String(translated[k]));
    return "" + doc.html();
}

function TJ(input, java, cache) {
    var root;
    try { root = JSON.parse(String(input)); } catch (e) { return input; }
    var paths = [];
    var texts = [];
    function collect(value, parent, key) {
        if (typeof value === "string") {
            paths.push({parent: parent, key: key});
            texts.push(value);
            return;
        }
        if (!value || typeof value !== "object") return;
        for (var child in value) {
            if (!Object.prototype.hasOwnProperty.call(value, child)) continue;
            if (child === "href" || child === "path") continue;
            collect(value[child], value, child);
        }
    }
    collect(root, null, null);
    var translated = TT(texts, java, cache);
    for (var i = 0; i < paths.length; i++) paths[i].parent[paths[i].key] = translated[i];
    return JSON.stringify(root);
}

